def max_revenue(N: int, S: List[int]) -> int:
    def count_distinct_prime_factors(x):
        if x <= 1:
            return 0
        count = 0
        for i in range(2, int(math.sqrt(x)) + 1):
            while x % i == 0:
                x //= i
                if count == 0:
                    count += 1
        if x > 1:
            count += 1
        return count

    def subset_sum_with_prime_factors(S):
        dp = [set() for _ in range(N + 1)]
        dp[0] = {0}
        for num in S:
            for j in range(N, num - 1, -1):
                dp[j].update({p + num for p in dp[j - num]})
        return dp[-1]

    prime_factors_set = subset_sum_with_prime_factors(S)
    return max(prime_factors_set)

